using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool Definitions ---

var notes = new List<string>();

[Description("Search the web for information on a given query. Returns relevant snippets.")]
string WebSearch(string query)
{
    Console.WriteLine($"  [Tool] Searching the web for: \"{query}\"");
    // Simulated web search results for demonstration purposes.
    var results = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
    {
        ["quantum computing"] = """
            1. Quantum computers use qubits that can exist in superposition, enabling parallel computation.
            2. Google achieved quantum supremacy in 2019 with their Sycamore processor (53 qubits).
            3. IBM launched a 1,121-qubit processor (Condor) in 2023 and targets error-corrected systems by 2029.
            4. Key applications include cryptography, drug discovery, materials science, and optimization problems.
            5. Current challenges: decoherence, error rates, and extreme cooling requirements (near absolute zero).
            """,
        ["AI agents"] = """
            1. AI agents are autonomous systems that perceive their environment and take actions to achieve goals.
            2. Modern AI agents use LLMs as reasoning engines combined with tool use and memory.
            3. ReAct (Reasoning + Acting) is a popular pattern where agents think step-by-step then act.
            4. Key frameworks: AutoGen, Semantic Kernel, LangChain, CrewAI.
            5. Challenges include hallucination, reliability, cost management, and safety guardrails.
            """,
        [".NET 10"] = """
            1. .NET 10 is the latest LTS release, focusing on cloud-native and AI workloads.
            2. Includes first-class support for AI via Microsoft.Extensions.AI abstractions.
            3. Performance improvements in JIT, GC, and Native AOT compilation.
            4. Enhanced container support and improved minimal APIs.
            5. Built-in OpenAPI document generation and new LINQ operators.
            """
    };

    foreach (var kvp in results)
    {
        if (query.Contains(kvp.Key, StringComparison.OrdinalIgnoreCase))
            return kvp.Value;
    }

    return $"Search results for '{query}': General information about this topic is available. " +
           "The topic is actively researched with new developments emerging regularly.";
}

[Description("Save a note to the research notebook. Use this to record key findings.")]
string TakeNote(string note)
{
    notes.Add(note);
    Console.WriteLine($"  [Tool] Note saved ({notes.Count} total)");
    return $"Note saved. You now have {notes.Count} note(s).";
}

[Description("Retrieve all saved research notes.")]
string GetNotes()
{
    if (notes.Count == 0)
        return "No notes saved yet.";
    return string.Join("\n", notes.Select((n, i) => $"{i + 1}. {n}"));
}

// --- Agent Setup ---

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "demo-key";
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var tools = new[]
{
    AIFunctionFactory.Create(WebSearch),
    AIFunctionFactory.Create(TakeNote),
    AIFunctionFactory.Create(GetNotes)
};

var chatOptions = new ChatOptions { Tools = [.. tools] };

// --- Agent Loop ---

var topic = args.Length > 0 ? string.Join(' ', args) : "quantum computing";

Console.WriteLine($"Research Agent Starting...");
Console.WriteLine($"Researching topic: \"{topic}\"\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a given topic thoroughly by:
        1. Searching the web for relevant information (make 2-3 searches with different queries)
        2. Taking notes on key findings as you discover them
        3. After gathering enough information, retrieve your notes and provide a final summary

        Be systematic: search, take notes on what you find, then summarize.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}")
};

Console.WriteLine("Agent is working...\n");

var response = await client.GetResponseAsync(messages, chatOptions);

Console.WriteLine("\n========== RESEARCH SUMMARY ==========\n");
Console.WriteLine(response.Text);

if (notes.Count > 0)
{
    Console.WriteLine("\n========== RESEARCH NOTES ==========\n");
    for (int i = 0; i < notes.Count; i++)
        Console.WriteLine($"  {i + 1}. {notes[i]}");
}

Console.WriteLine("\n=======================================");

